package loop

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"os"
	"strings"
	"sync/atomic"
	"testing"
	"time"

	"github.com/KogenAI/kogen-loop/api"
	"github.com/KogenAI/kogen-loop/provider"
	"github.com/KogenAI/kogen-loop/sys"
	"github.com/KogenAI/kogen-loop/tools"
)

// rulesRound runs one session round against a local openai-compatible server on one injected
// clock. answer is told the request number among the non-summarization requests and the body;
// it advances the clock and returns the status and body of its answer. The provider client's
// Sleep seam does not wait, so a retry wait costs no real time and no injected time.
func rulesRound(t *testing.T, answer func(clock *modelMSClock, n int, summary bool) (int, string)) []api.Event {
	t.Helper()
	clock := &modelMSClock{t: time.Date(2026, 11, 20, 10, 0, 0, 0, time.UTC)}
	var n atomic.Int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		summary := strings.Contains(string(body), "You condense the earlier work")
		i := 0
		if !summary {
			i = int(n.Add(1))
		}
		status, text := answer(clock, i, summary)
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(status)
		io.WriteString(w, text)
	}))
	defer srv.Close()
	client := provider.NewClient("test")
	client.Sleep = func(ctx context.Context, _ time.Duration) error { return ctx.Err() }
	root := t.TempDir()
	var events []api.Event
	s, err := NewSession(SessionConfig{
		Root: root, Role: provider.Role{Provider: "openai-compatible", Model: "local", BaseURL: srv.URL},
		Session: sys.NewWith([]string{"HOME=" + t.TempDir(), "PATH=" + os.Getenv("PATH")}, root),
		Client:  client,
		Emit:    func(e api.Event) { events = append(events, e) },
	})
	if err != nil {
		t.Fatal(err)
	}
	s.tools.Now = clock.now
	s.tools.Enabled = append(s.tools.Enabled, tools.ProbeTool)
	s.tools.Probe = func(string, any) (string, error) { return strings.Repeat("a", 20000), nil }
	res, err := s.Round(context.Background(), "go")
	if err != nil || res.Ending != EndTerminal {
		t.Fatalf("%+v %v", res, err)
	}
	return events
}

func rulesCalls(names ...string) string {
	var parts []string
	for i, n := range names {
		args := `{}`
		if n == "finish" {
			args = `{\"summary\":\"done\"}`
		} else {
			args = `{\"command\":\"x\"}`
		}
		parts = append(parts, fmt.Sprintf(`{"id":"c%d","type":"function","function":{"name":"%s","arguments":"%s"}}`, i, n, args))
	}
	return fmt.Sprintf(`{"choices":[{"message":{"role":"assistant","content":null,"tool_calls":[%s]},"finish_reason":"tool_calls"}]}`, strings.Join(parts, ","))
}

// A request the provider call retries is one turn: the failed attempt's 100 ms and the
// answering attempt's 200 ms are both inside the one response event's model_ms of 300.
func TestSessionRetriedRequestIsOneTurnModelMS(t *testing.T) {
	t.Parallel()
	events := rulesRound(t, func(clock *modelMSClock, n int, _ bool) (int, string) {
		if n == 1 {
			clock.advance(100)
			return http.StatusInternalServerError, `{"error":{"message":"temporary"}}`
		}
		clock.advance(200)
		return http.StatusOK, rulesCalls("finish")
	})
	var model []any
	for _, e := range events {
		if e.Type == api.EventResponse {
			model = append(model, e.Fields["model_ms"])
		}
	}
	if len(model) != 1 {
		t.Fatalf("%d response events, want 1", len(model))
	}
	if ms, ok := model[0].(int64); !ok || ms != 300 {
		t.Errorf("model_ms %T %v, want int64 300", model[0], model[0])
	}
}

// Only response events carry model_ms: in a round that condenses its context once, every
// response event has it as an integer and no other event, context.condensed included, has the key.
func TestSessionOnlyResponseEventsCarryModelMS(t *testing.T) {
	t.Parallel()
	// Two turns of 20 probe results of 16384 bytes each pass the 524288-byte request ceiling
	// together, so the third request is condensed.
	calls := make([]string, 20)
	for i := range calls {
		calls[i] = "probe"
	}
	events := rulesRound(t, func(clock *modelMSClock, n int, summary bool) (int, string) {
		clock.advance(10)
		if summary {
			return http.StatusOK, `{"choices":[{"message":{"role":"assistant","content":"summary of earlier work"},"finish_reason":"stop"}]}`
		}
		if n <= 2 {
			return http.StatusOK, rulesCalls(calls...)
		}
		return http.StatusOK, rulesCalls("finish")
	})
	condensed, responses := 0, 0
	for _, e := range events {
		_, has := e.Fields["model_ms"]
		switch e.Type {
		case api.EventResponse:
			responses++
			if _, ok := e.Fields["model_ms"].(int64); !ok {
				t.Errorf("response model_ms %T %v", e.Fields["model_ms"], e.Fields["model_ms"])
			}
		case api.EventContextCondensed:
			condensed++
			fallthrough
		default:
			if has {
				t.Errorf("%s event has model_ms", e.Type)
			}
		}
	}
	if condensed != 1 || responses != 3 {
		t.Errorf("%d context.condensed and %d response events, want 1 and 3", condensed, responses)
	}
}

